/* ---- FEEDER SERVO on GPIO43 (LEDC channel 1 / timer 1, 50 Hz) -------------
 * The camera's XCLK already uses LEDC ch0/timer0 at 20 MHz, so the servo takes
 * ch1/timer1. Hobby servo: 20 ms period, ~1.0 ms pulse = closed, ~2.0 ms = open.
 * timer1: 80 MHz / 97.65625 / 2^14 = 50 Hz  (period = 16384 duty counts).
 *   clk_div fixed point = int 97 (<<12) | frac 168 (<<4)  -> 97.65625
 */
#define SERVO_PIN            43
#define R_LEDC_CH1_CONF0     (LEDC_BASE + 0x14)
#define R_LEDC_CH1_HPOINT    (LEDC_BASE + 0x18)
#define R_LEDC_CH1_DUTY      (LEDC_BASE + 0x1c)
#define R_LEDC_CH1_CONF1     (LEDC_BASE + 0x20)
#define R_LEDC_TIMER1_CONF   (LEDC_BASE + 0xa8)
#define SERVO_DUTY_BITS      14
#define SERVO_PERIOD_CNT     16384          /* 2^14, = 20 ms */

/* PADDLE-ROTOR metering (hardware/velapaw_feeder.scad).
 *
 * The rotor has ROTOR_POCKETS vanes running in a round housing under the
 * hopper. One pocket holds a FIXED VOLUME of kibble, so the portion depends on
 * how many pockets we index -- NOT on how long a gate stays open, and NOT on
 * how full the hopper is. That is the entire reason for the rotor: a flap's
 * dose grows with hopper weight, which would quietly wreck the per-pet portion
 * control the product is built on.
 *
 * The MG90S is a 180-degree servo, so we cannot spin the rotor continuously.
 * Instead each pocket is one OSCILLATION: sweep forward by one pocket angle
 * (carrying a full pocket from the inlet round to the outlet, where it drops),
 * then sweep back (returning the now-empty pocket under the inlet to refill).
 * grams = pockets x GRAMS_PER_POCKET.
 *
 * 1000us = 0 deg, 2000us = 180 deg  =>  us = 1000 + deg * 1000/180.
 */
#define ROTOR_POCKETS        6              /* vanes; must match the .scad */
#define ROTOR_POCKET_DEG     (360 / ROTOR_POCKETS)   /* 60 deg per pocket */
#define SERVO_HOME_US        1000           /* rotor at rest */
#define SERVO_STEP_US        (SERVO_HOME_US + ROTOR_POCKET_DEG * 1000 / 180)
#define SERVO_MOVE_MS        400            /* time to complete one sweep */
#define GRAMS_PER_POCKET     5              /* CALIBRATE: weigh one pocket */

static void servo_set_us(int us)
{
  uint32_t duty = (uint32_t)(((long)us * SERVO_PERIOD_CNT) / 20000);
  wreg(R_LEDC_CH1_DUTY, duty << 4);         /* duty has 4 fractional bits */
  sreg(R_LEDC_CH1_CONF0, B_LEDC_CH0_PARAUP);
}

void board_feeder_init(void)
{
  sreg(R_SYS_CLK_EN0, B_SYS_LEDC);
  creg(R_SYS_RST_EN0, B_SYS_LEDC);
  wreg(R_LEDC_CONF, 1);                     /* APB clock source */
  sreg(R_LEDC_CONF, B_LEDC_CLK_EN);

  sreg(R_LEDC_TIMER1_CONF, B_LEDC_T0_RST);
  wreg(R_LEDC_TIMER1_CONF,
       (SERVO_DUTY_BITS << S_LEDC_DUTYRES) |
       (168u << S_LEDC_CLKDIV) |            /* frac .65625 */
       (97u  << (S_LEDC_CLKDIV + 8)));      /* int  97     */
  sreg(R_LEDC_TIMER1_CONF, B_LEDC_T0_PARAUP);

  wreg(R_LEDC_CH1_CONF0, 1);                /* channel1 -> timer1 */
  wreg(R_LEDC_CH1_CONF1, 0);
  wreg(R_LEDC_CH1_HPOINT, 0);
  servo_set_us(SERVO_HOME_US);
  sreg(R_LEDC_CH1_CONF0, B_LEDC_CH0_SIGOUT);
  sreg(R_LEDC_CH1_CONF1, B_LEDC_CH0_DUTYST);
  sreg(R_LEDC_CH1_CONF0, B_LEDC_CH0_PARAUP);

  esp32s3_configgpio(SERVO_PIN, OUTPUT);
  esp32s3_gpio_matrix_out(SERVO_PIN, LEDC_SIG_OUT0_IDX + 1, 0, 0);
  syslog(LOG_ERR,"[feeder] servo ready on GPIO%d (50Hz)\n", SERVO_PIN);
}

/* Index the rotor one pocket: sweep forward (drops a pocket at the outlet),
 * then back (refills the empty pocket from the hopper). */
static void rotor_index_one(void)
{
  servo_set_us(SERVO_STEP_US);
  nxsig_usleep(SERVO_MOVE_MS * 1000);
  servo_set_us(SERVO_HOME_US);
  nxsig_usleep(SERVO_MOVE_MS * 1000);
}

/* Dispense `grams` by indexing whole pockets (rounded to nearest). MUST NOT run
 * on the UI thread (it sleeps ~0.8s per pocket): the app calls this from a
 * detached worker thread -- see hal/feeder_servo.c. */
int board_feeder_dispense(int grams)
{
  int pockets;
  int i;

  if (grams <= 0) return -1;

  /* round to the nearest whole pocket; always give at least one */
  pockets = (grams + GRAMS_PER_POCKET / 2) / GRAMS_PER_POCKET;
  if (pockets < 1) pockets = 1;

  for (i = 0; i < pockets; i++)
    {
      rotor_index_one();
    }

  syslog(LOG_ERR, "[feeder] dispensed %d pocket(s) ~%dg (asked %dg)\n",
         pockets, pockets * GRAMS_PER_POCKET, grams);
  return 0;
}

