/* ---- FEEDER: 28BYJ-48 stepper via ULN2003 --------------------------------
 * Replaces the earlier hobby servo. The servo could only OSCILLATE (zero net
 * rotation), and with the rotor's inlet and outlet 180 deg apart a pocket
 * filled at the inlet could never reach the outlet -- it dead-headed after the
 * first charge. A stepper rotates CONTINUOUSLY one direction, so pockets ratchet
 * inlet->outlet every time and "grams = pockets x GRAMS_PER_POCKET" is exact.
 *
 * Wiring: ULN2003 IN1..IN4 <- these four GPIOs; the ULN2003 is powered from a
 * separate 5V supply with a COMMON GROUND to the board. GPIO12/13/15/16 (first
 * chosen in firmware) are the ES8311 audio lines and are NOT on the 2x16 header,
 * so we drive four pins that ARE broken out and free (SD off, console on USB).
 */
#define STEP_IN1             9
#define STEP_IN2             10
#define STEP_IN3             11
#define STEP_IN4             44

#define ROTOR_POCKETS        6              /* vanes; must match the .scad */
#define STEP_PER_REV         4096           /* 28BYJ-48 half-step (64:1 gear) */
#define STEP_PER_POCKET      (STEP_PER_REV / ROTOR_POCKETS)   /* ~682 */
#define STEP_DELAY_US        1500           /* per half-step; ~667 steps/s */
#define GRAMS_PER_POCKET     5              /* CALIBRATE: weigh one pocket */

/* 8-phase half-step sequence; bit0=IN1 bit1=IN2 bit2=IN3 bit3=IN4 */
static const uint8_t k_halfstep[8] =
  { 0x8, 0xC, 0x4, 0x6, 0x2, 0x3, 0x1, 0x9 };

static void step_coils(uint8_t m)
{
  esp32s3_gpiowrite(STEP_IN1, (m & 0x1) != 0);
  esp32s3_gpiowrite(STEP_IN2, (m & 0x2) != 0);
  esp32s3_gpiowrite(STEP_IN3, (m & 0x4) != 0);
  esp32s3_gpiowrite(STEP_IN4, (m & 0x8) != 0);
}

void board_feeder_init(void)
{
  esp32s3_configgpio(STEP_IN1, OUTPUT);
  esp32s3_configgpio(STEP_IN2, OUTPUT);
  esp32s3_configgpio(STEP_IN3, OUTPUT);
  esp32s3_configgpio(STEP_IN4, OUTPUT);
  step_coils(0);                            /* coils de-energised at rest */
  syslog(LOG_ERR, "[feeder] 28BYJ-48 stepper ready on GPIO %d/%d/%d/%d\n",
         STEP_IN1, STEP_IN2, STEP_IN3, STEP_IN4);
}

/* Dispense `grams` by rotating whole pockets. One-direction continuous spin, so
 * every pocket carries inlet->outlet. MUST NOT run on the UI thread (it busy-
 * waits ~1s per pocket): the app calls it from a detached worker thread. */
int board_feeder_dispense(int grams)
{
  int pockets;
  int steps;
  int i;
  int phase = 0;

  if (grams <= 0) return -1;

  /* round to the nearest whole pocket; always give at least one */
  pockets = (grams + GRAMS_PER_POCKET / 2) / GRAMS_PER_POCKET;
  if (pockets < 1) pockets = 1;
  steps = pockets * STEP_PER_POCKET;

  for (i = 0; i < steps; i++)
    {
      step_coils(k_halfstep[phase & 7]);
      phase++;                              /* one direction => pockets ratchet */
      up_udelay(STEP_DELAY_US);
    }
  step_coils(0);                            /* release coils (no holding current) */

  syslog(LOG_ERR, "[feeder] dispensed %d pocket(s) ~%dg (%d steps, asked %dg)\n",
         pockets, pockets * GRAMS_PER_POCKET, steps, grams);
  return 0;
}

