void board_feeder_init(void)
{
  int cyc;
  int c;

  esp32s3_configgpio(STEP_IN1, OUTPUT);
  esp32s3_configgpio(STEP_IN2, OUTPUT);
  esp32s3_configgpio(STEP_IN3, OUTPUT);
  esp32s3_configgpio(STEP_IN4, OUTPUT);
  step_coils(0);                            /* coils de-energised at rest */

  /* --- BOOT DIAGNOSTIC (one-shot): energise each coil ALONE for 0.5s in the
   * order IN1(A)->IN2(B)->IN3(C)->IN4(D), 4 times. With straight wiring
   * (IN1..IN4 <- GPIO 9/10/11/44) each ULN2003 LED must light one-at-a-time in
   * turn. Any LED that never lights = that GPIO is not driving; any LED that
   * stays solid through the whole walk = that GPIO is clamped (e.g. UART pin).
   * Remove once the four lines are confirmed good. --- */
  for (cyc = 0; cyc < 4; cyc++)
    {
      for (c = 0; c < 4; c++)
        {
          step_coils((uint8_t)(1u << c));   /* only coil c energised */
          up_udelay(500000);                /* 0.5s, clearly visible */
        }
    }
  step_coils(0);

  syslog(LOG_ERR, "[feeder] 28BYJ-48 stepper ready on GPIO %d/%d/%d/%d\n",
         STEP_IN1, STEP_IN2, STEP_IN3, STEP_IN4);
}

