/* Claim all four coil lines as plain GPIO outputs. MUST be re-called right
 * before each dispense: board_feeder_init() runs early in bringup, but the
 * UART0 driver initialises AFTER it and re-muxes its RX pin (GPIO44) back to
 * the UART peripheral -- clamping IN4 solid-high. Re-asserting the IOMUX to
 * GPIO output here detaches UART again and reclaims the pin for stepping.
 * (Console is on USB-Serial/JTAG, so stealing UART0's pins costs nothing.) */
static void feeder_pins_output(void)
{
  esp32s3_configgpio(STEP_IN1, OUTPUT);
  esp32s3_configgpio(STEP_IN2, OUTPUT);
  esp32s3_configgpio(STEP_IN3, OUTPUT);
  esp32s3_configgpio(STEP_IN4, OUTPUT);
}

void board_feeder_init(void)
{
  feeder_pins_output();
  step_coils(0);                            /* coils de-energised at rest */
  syslog(LOG_ERR, "[feeder] 28BYJ-48 stepper ready on GPIO %d/%d/%d/%d\n",
         STEP_IN1, STEP_IN2, STEP_IN3, STEP_IN4);
}

