/* --- COIL-ORDER SWEEP DIAGNOSTIC ---------------------------------------------
 * Straight coil order (IN1,IN2,IN3,IN4) only buzzes, and full-step + slow speed
 * proved it is NOT a stall. For a 4-wire stepper there are exactly three
 * distinct coil-order topologies; straight is one, so the motor is wired as one
 * of the other two. Drive each candidate as full-step for ~1/2 rev with a clear
 * ~2s pause between, so we can SEE which one rotates:
 *
 *   SEGMENT 1  = order IN1,IN2,IN4,IN3   (pairs 0x3,0xA,0xC,0x5)
 *   (pause)
 *   SEGMENT 2  = order IN1,IN3,IN2,IN4   (pairs 0x5,0x6,0xA,0x9)
 *
 * Whichever segment actually turns the shaft is the correct topology; then we
 * lock its sequence in and restore the normal gram-based dispense.
 * ---------------------------------------------------------------------------*/
static const uint8_t k_cand1[4] = { 0x3, 0xA, 0xC, 0x5 };  /* IN1,IN2,IN4,IN3 */
static const uint8_t k_cand2[4] = { 0x5, 0x6, 0xA, 0x9 };  /* IN1,IN3,IN2,IN4 */

static void feeder_pause_ms(int ms)
{
  int k;
  for (k = 0; k < ms; k++) up_udelay(1000);
}

int board_feeder_dispense(int grams)
{
  int i;
  (void)grams;

  feeder_pins_output();                     /* reclaim GPIO44 from UART0 */

  /* SEGMENT 1 */
  for (i = 0; i < 1024; i++) { step_coils(k_cand1[i & 3]); up_udelay(3000); }
  step_coils(0);
  feeder_pause_ms(2000);                     /* ~2s visible gap, coils off */

  /* SEGMENT 2 */
  for (i = 0; i < 1024; i++) { step_coils(k_cand2[i & 3]); up_udelay(3000); }
  step_coils(0);

  syslog(LOG_ERR, "[feeder] sweep done: seg1=IN1243 seg2=IN1324\n");
  return 0;
}

