Here's the complete stepper driver (the clean production version — with the UART-reclaim fix and full-step drive, minus the temporary sweep diagnostic). This is the `board_feeder_*` block from the board file `esp32s3_st7789.c`:

```c
/* ==========================================================================
 * 28BYJ-48 stepper feeder (ULN2003 driver)
 *
 * Wiring: ULN2003 IN1..IN4 <- these four GPIOs. The ULN2003 is powered from a
 * separate 5V >=2A supply with a COMMON GROUND to the ESP32-S3. The 28BYJ-48's
 * white 5-pin connector plugs into the ULN2003 (red = +5V centre-tap).
 *
 * GPIO 9/10/11 are broken out on the 2x16 header (SD off) and GPIO44 is UART0
 * RX -- free because the console runs on USB-Serial/JTAG, not UART0.
 * ========================================================================== */
#define STEP_IN1             9
#define STEP_IN2             10
#define STEP_IN3             11
#define STEP_IN4             44

#define ROTOR_POCKETS        6              /* vanes; must match the .scad */
#define STEP_PER_REV         2048           /* 28BYJ-48 FULL-step (64:1 gear) */
#define STEP_PER_POCKET      (STEP_PER_REV / ROTOR_POCKETS)   /* ~341 */
#define STEP_DELAY_US        3000           /* per full-step; ~333 steps/s, within pull-in torque */
#define GRAMS_PER_POCKET     5              /* CALIBRATE: weigh one pocket */

/* 4-phase FULL-step sequence: two adjacent coils on each step => ~2x torque vs
 * single-coil half-step phases, so the geared rotor pulls in instead of
 * stalling into a buzz. bit0=IN1 bit1=IN2 bit2=IN3 bit3=IN4 */
static const uint8_t k_fullstep[4] =
  { 0x3, 0x6, 0xC, 0x9 };                   /* IN1+2, IN2+3, IN3+4, IN4+1 */

static void step_coils(uint8_t m)
{
  esp32s3_gpiowrite(STEP_IN1, (m & 0x1) != 0);
  esp32s3_gpiowrite(STEP_IN2, (m & 0x2) != 0);
  esp32s3_gpiowrite(STEP_IN3, (m & 0x4) != 0);
  esp32s3_gpiowrite(STEP_IN4, (m & 0x8) != 0);
}

/* Claim all four coil lines as plain GPIO outputs. MUST be re-called right
 * before each dispense: board_feeder_init() runs early in bringup, but the
 * UART0 driver initialises AFTER it and re-muxes its RX pin (GPIO44) back to
 * the UART peripheral -- clamping IN4 solid-high. Re-asserting the IOMUX to
 * GPIO output here detaches UART again and reclaims the pin for stepping. */
static void feeder_pins_output(void)
{
  esp32s3_configgpio(STEP_IN1, OUTPUT);
  esp32s3_configgpio(STEP_IN2, OUTPUT);
  esp32s3_configgpio(STEP_IN3, OUTPUT);
  esp32s3_configgpio(STEP_IN4, OUTPUT);
}

void board_feeder_init(void)
{
  feeder_pins_output();
  step_coils(0);                            /* coils de-energised at rest */
  syslog(LOG_ERR, "[feeder] 28BYJ-48 stepper ready on GPIO %d/%d/%d/%d\n",
         STEP_IN1, STEP_IN2, STEP_IN3, STEP_IN4);
}

/* Dispense `grams` by rotating whole pockets. One-direction continuous spin, so
 * every pocket carries inlet->outlet. MUST NOT run on the UI thread (it busy-
 * waits ~1s per pocket): the app calls it from a detached worker thread. */
int board_feeder_dispense(int grams)
{
  int pockets;
  int steps;
  int i;
  int phase = 0;

  if (grams <= 0) return -1;

  feeder_pins_output();                     /* reclaim GPIO44 from UART0 before stepping */

  /* round to the nearest whole pocket; always give at least one */
  pockets = (grams + GRAMS_PER_POCKET / 2) / GRAMS_PER_POCKET;
  if (pockets < 1) pockets = 1;
  steps = pockets * STEP_PER_POCKET;

  for (i = 0; i < steps; i++)
    {
      step_coils(k_fullstep[phase & 3]);
      phase++;                              /* one direction => pockets ratchet */
      up_udelay(STEP_DELAY_US);
    }
  step_coils(0);                            /* release coils (no holding current) */

  syslog(LOG_ERR, "[feeder] dispensed %d pocket(s) ~%dg (%d steps, asked %dg)\n",
         pockets, pockets * GRAMS_PER_POCKET, steps, grams);
  return 0;
}
```

**Notes on this code vs. what's flashed right now:**
- The board currently has the **sweep diagnostic** in `board_feeder_dispense` (two topology segments), not this gram-based version. This block above is what I'd restore once the motor is confirmed good.
- To try **half-step** instead (finer, smoother, but half the torque), swap the sequence table and index:
  ```c
  static const uint8_t k_halfstep[8] = { 0x1, 0x3, 0x2, 0x6, 0x4, 0xC, 0x8, 0x9 };
  /* ...and in the loop: */  step_coils(k_halfstep[phase & 7]);
  /* ...with STEP_PER_REV 4096 */
  ```

Everything electrical in this code is confirmed working on your board (all four GPIOs drive, UART reclaim works). Given the sweep showed **no rotation in any of the three possible coil orders**, the remaining fault is in the **motor/connector itself**, not this code.

