//             front; the camera (board back) looks BACK-and-down at the bowl.
LAYOUT = "back"; // [back:screen behind / camera over bowl, front:screen faces owner up front]

// ---- "back" layout aim (camera over the bowl) ------------------------------
CAM_MOUNT_Y  = -68;   // camera/board position along the drum axis; pushed FORWARD of
                      // the funnel so the tilted screen never touches the funnel flare
